(({F:e})=>{function t(e){return(e||"periode").toLocaleLowerCase("nn")}let r={day:"I dag",week:"Denne veka",month:"Denne månaden",year:"I år"},n={code:"nn",week:{dow:1,doy:4},prevText:"Førre",nextText:"Neste",todayText:"I dag",yearText:"År",monthText:"Månad",weekTextLong:"Veke",dayText:"Dag",listText:"Agenda",allDayText:"Heile\ndagen",moreLinkText:"til",noEventsText:"Ingen hendingar å vise",prevHint(e){return"Førre "+t(e)},nextHint(e){return"Neste "+t(e)},todayHint(e,n){return r[n]||"Noverande "+t(e)},viewHint(e){return"Vis "+t(e)},navLinkHint:"Gå til $0",moreLinkHint(e){return`Vis ${e} hending${1===e?"":"ar"} til`},closeHint:"Lukk",eventsHint:"Hendingar"};e.push(n)})(FullCalendar.Shared);